import itertools, sys

def find_gadget(max_aux=3, max_clauses=4):
    base_vars = ['p','n']
    for aux_count in range(1, max_aux+1):
        aux = [chr(ord('a')+i) for i in range(aux_count)]
        vars = base_vars + aux
        # generate all possible 3-element subsets (order irrelevant) of vars
        triples = list(itertools.combinations(vars,3))
        for r in range(1, max_clauses+1):
            for clause_set in itertools.combinations(triples, r):
                # test condition
                def sat(assign):
                    for cl in clause_set:
                        if sum(assign[v] for v in cl) != 1:
                            return False
                    return True
                # check all assignments of all vars
                good = []
                for bits in itertools.product([0,1], repeat=len(vars)):
                    assign = dict(zip(vars, bits))
                    if sat(assign):
                        good.append(assign)
                # condition: there exists assignment with p!=n, and no assignment with p==n
                has_diff = any(g['p']!=g['n'] for g in good)
                has_eq = any(g['p']==g['n'] for g in good)
                if has_diff and not has_eq:
                    print('Found gadget with aux', aux, 'clauses', clause_set)
                    return clause_set, aux
    return None

res = find_gadget()
